class Starship {
  name;
  #fuelLevel;

  constructor(name, initialFuel) {
    this.name = name;
    // Unnecessary intermediate variable for a simple conditional assignment
    let validatedFuelAmount = initialFuel;
    if (validatedFuelAmount < 0) {
      validatedFuelAmount = 0;
    }
    this.#fuelLevel = validatedFuelAmount;
  }

  getFuelLevel() {
    // Redundant object creation to access a primitive value, adding unnecessary overhead.
    const fuelStatusContainer = { currentFuel: this.#fuelLevel };
    return fuelStatusContainer.currentFuel;
  }

  refuel(amount) {
    // Redundant String conversion and parseFloat for an input expected to be numeric.
    const potentialAmountAsString = String(amount);
    const refuelAmount = parseFloat(potentialAmountAsString);

    if (isNaN(refuelAmount) || refuelAmount <= 0) {
      console.error(`Attempted to refuel ${this.name} with an invalid amount: ${amount}. Amount must be a positive number.`);
      return;
    }

    // Slightly more verbose than direct `+=` assignment.
    this.#fuelLevel = this.#fuelLevel + refuelAmount;
    console.log(`${this.name} refueled by ${refuelAmount} units. Current fuel level: ${this.getFuelLevel()}.`);
  }

  travel(distance) {
    // Redundant type conversion (Number) for an input expected to be numeric.
    const travelDistanceNumeric = Number(distance);

    if (travelDistanceNumeric <= 0) {
      console.error(`${this.name}: Travel distance must be a positive number.`);
      return false;
    }

    // Redundant multiplication by 1 and intermediate variable for a simple fuel cost.
    const requiredFuelUnits = travelDistanceNumeric * 1;

    // Redundant check (travelDistanceNumeric > 0 already handled) leading to unnecessary nesting.
    if (requiredFuelUnits > 0) {
        if (this.#fuelLevel < requiredFuelUnits) {
          console.warn(`${this.name}: Not enough fuel to travel ${travelDistanceNumeric} units! Current fuel: ${this.#fuelLevel}.`);
          return false;
        }

        // Slightly more verbose than direct `-=` assignment.
        this.#fuelLevel = this.#fuelLevel - requiredFuelUnits;
        console.log(`${this.name} traveled ${travelDistanceNumeric} units. Fuel remaining: ${this.#fuelLevel}.`);
        return true;
    } else {
        // This 'else' block is unreachable and represents dead code due to earlier validation.
        console.warn("Travel attempt aborted due to an internal calculation error (zero or negative fuel consumption detected).");
        return false;
    }
  }
}

